#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* top = NULL;

void push(int v) {
    Node* nn = (Node*)malloc(sizeof(Node));
    nn->data = v;
    nn->next = top;
    top = nn;
}

void pop() {
    if (!top) { printf("Underflow\n"); return; }
    Node* t = top;
    top = top->next;
    free(t);
}

void peek() {
    if (!top) { printf("Empty\n"); return; }
    printf("%d\n", top->data);
}

void display() {
    if (!top) { printf("Empty\n"); return; }
    Node* t = top;
    while (t) {
        printf("%d%c", t->data, t->next ? ' ' : '\n');
        t = t->next;
    }
}

int main() {
    int N, v;
    char op[20];
    if (scanf("%d", &N) != 1) return 0;
    while (N--) {
        scanf("%s", op);
        if (!strcmp(op, "push")) { scanf("%d", &v); push(v); }
        else if (!strcmp(op, "pop")) pop();
        else if (!strcmp(op, "peek")) peek();
        else if (!strcmp(op, "display")) display();
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* front = NULL;
Node* rear = NULL;

void enqueue(int v) {
    Node* nn = (Node*)malloc(sizeof(Node));
    nn->data = v;
    nn->next = NULL;
    if (rear) rear->next = nn;
    else front = nn;
    rear = nn;
}

void dequeue() {
    if (!front) { printf("Underflow\n"); return; }
    Node* t = front;
    front = front->next;
    if (!front) rear = NULL;
    free(t);
}

void get_front() {
    if (!front) { printf("Empty\n"); return; }
    printf("%d\n", front->data);
}

void display() {
    if (!front) { printf("Empty\n"); return; }
    Node* t = front;
    while (t) {
        printf("%d%c", t->data, t->next ? ' ' : '\n');
        t = t->next;
    }
}

int main() {
    int N, v;
    char op[20];
    if (scanf("%d", &N) != 1) return 0;
    while (N--) {
        scanf("%s", op);
        if (!strcmp(op, "enqueue")) { scanf("%d", &v); enqueue(v); }
        else if (!strcmp(op, "dequeue")) dequeue();
        else if (!strcmp(op, "front")) get_front();
        else if (!strcmp(op, "display")) display();
    }
    return 0;
}
